import re
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime
from contextlib import contextmanager
from inspect import currentframe
from logging import Logger
from os import path
from subprocess import call, check_output
from pexpect import spawn

from taf.sbts.oam.coam.admin import admin as taf_admin
from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import enb_data, SERVER_HOST
from ta_logcollector.utils.common import run_remote_cmd
from ta_logcollector.utils.internal import get_hw_type

logger = Logger("LC")

TSHARK_CMDS = {
    "rrc_iphy": (
        '/usr/bin/tshark -i any -B 20 -f "not sctp and ({})" -T fields -e frame.time_epoch '
        '-e iphy.ue_id -e iphy.message.type -e iphy.data -w "{}"'
    ),
    "rrc_cus": (
        '/usr/bin/tshark -i eth4 -B 20 -f "not sctp and ({})" -T fields -e frame.time_epoch '
        '-e cus.ue_id -e cus.msg_type -e cus.data -w "{}"'
    ),
    "others": '/usr/bin/tshark -f "sctp and ({})" -i any -F pcapng -w "{}"',
}
TSHARK_FILTERS = {
    "rrc_iphy": (
        "ip[38:2]=0x41 or ip[38:2]=0x42 or ip[38:2]=0x45 or ip[38:2]=0x46 or ip[38:2]=0x7 or ip[38:2]=0x48 or "
        "ip[38:2]=0x36 or ip[38:2]=0x38 or ip[6:1]=0x20 or ip[7:1]>0x0 or ip[38:2]=0x28 or ip[38:2]=0x3e or "
        "ip[38:2]=0x3f or ip[38:2]=0x40"
    ),
    "rrc_cus": "ip[63:1]=0xa0",
    "x2": "(ip[46:2]=0x1b or ip[62:2]=0x1b)",
    "s1": "(ip[46:2]=0x12 or ip[62:2]=0x12)",
    "m3": "(ip[46:2]=0x2c or ip[62:2]=0x2c)",
}
enb_log = "/rom/logs/X2S1_lte_backhaul.pcap"
X2AP_ALIAS_TEMPLATE = "LC_X2AP_MIRRORING_{}_{}"


def _get_mac_addr_of_iface(interface):
    # type (str) -> str
    ifcfg_out = check_output("cat /sys/class/net/{}/address".format(interface), shell=True)
    logger.debug("MAC raw output: {}".format(ifcfg_out))
    return ifcfg_out.decode().strip()


@contextmanager
def get_admin_connection(alias, log_dir):
    # type: (str, str) -> taf_admin
    admin = taf_admin()
    try:
        admin.setup_admin(alias=alias, admin_api_log_dir=log_dir)
        logger.debug("Opened connection with admin")
        yield admin
    except Exception as err:
        logger.debug(err)
        raise
    finally:
        try:
            admin.teardown_admin(alias=alias)
            logger.debug("Closed connection with admin")
        except Exception as err:
            logger.debug(err)


def _mirroring_with_taf_admin(admin_instance, alias, enable, mac_address=None, egress_port_dn=None, timeout=90):
    # type: (taf_admin, str, bool, Optional[str], Optional[str], int) -> None
    logger.debug("taf_admin action: {}".format("start" if enable else "stop"))
    if enable:
        admin_instance.start_ip_capture_streaming(
            measurement_point="NE_Terminated",
            uplane_capturing=True,
            dst_mac_addr=mac_address,
            egress_port_dn=egress_port_dn,
            timeout=timeout,
            alias=alias,
        )
        logger.debug("Mirroring enabled")
    else:
        admin_instance.stop_ip_capture_streaming(timeout=timeout, alias=alias)


def get_timestamp():
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def _start_mirroring_with_lmp(admin_instance, alias):
    # type: (taf_admin, str) -> None
    logger.debug("Trying to start mirroring with LMP")
    mac_addr = _get_mac_addr_of_iface("eth1")
    _mirroring_with_taf_admin(admin_instance, alias, enable=True, mac_address=mac_addr)


def get_ethlk_from_scf(admin_instance, alias):
    # type: (taf_admin, str) -> str
    scf = admin_instance.get_scf(alias=alias)
    match = re.search(r'distName="(.*ETHLK-\d+)"', scf)
    if match:
        return match.group(1)
    logger.debug("ETHLK not found. Falling back to default: 'MRBTS-1/TNLSVC-1/TNL-1/ETHSVC-1/ETHLK-2'")
    return "MRBTS-1/TNLSVC-1/TNL-1/ETHSVC-1/ETHLK-1"


def _start_mirroring_with_eif(admin_instance, alias):
    # type: (taf_admin, str) -> None
    logger.debug("Trying to start mirroring with EIF")
    mac_addr = _get_mac_addr_of_iface("eth3")
    ethlk_dn = get_ethlk_from_scf(admin_instance, alias)
    logger.debug("ETHLK = {}".format(ethlk_dn))
    _mirroring_with_taf_admin(admin_instance, alias, enable=True, mac_address=mac_addr, egress_port_dn=ethlk_dn)


def start_mirroring_for_x2(log_dir):
    # type: (str) -> None
    alias = X2AP_ALIAS_TEMPLATE.format("START", get_timestamp())
    try:
        with get_admin_connection(alias, log_dir) as admin_instance:
            try:
                _start_mirroring_with_lmp(admin_instance, alias)
            except Exception as err:
                logger.debug(err)
                _start_mirroring_with_eif(admin_instance, alias)
        logger.debug("X2 mirroring started.")
    except Exception as err:
        logger.debug("X2 mirroring failed: {}".format(err))


def start_tshark(proto_list, log_dir):
    # type: (List[str], str) -> Optional[spawn]
    logger.debug("Tshark for {} going to be started".format(proto_list))
    if "x2" in proto_list:
        start_mirroring_for_x2(log_dir)
    proto_type = proto_list[0] if any(protocol.startswith("rrc") for protocol in proto_list) else "others"
    cmd = TSHARK_CMDS[proto_type].format(
        " or ".join([TSHARK_FILTERS[proto] for proto in proto_list]),
        path.join(log_dir, "{}_{}.pcapng".format("_".join(proto_list), SERVER_HOST)),
    )
    is_alive, ts_pid = False, None
    try:
        tshark_process = spawn(cmd)
    except Exception as err:
        logger.debug(err)
    else:
        try:
            tshark_process.expect("Capturing on")
            is_alive = tshark_process.isalive()
            ts_pid = tshark_process.pid
            return tshark_process
        except Exception as exp:
            logger.debug(exp, exc_info=True)
            tshark_process.close()
    finally:
        logger.debug(
            "Protocol: {} is_alive: {} PID: {} for command: {}".format("_".join(proto_list), is_alive, ts_pid, cmd)
        )


def start(protocols, log_dir, run_remotely=False):
    # type: (Dict[str, bool], str, bool) -> Union[List[Union[spawn, taf_admin]], int]
    """
    Method should start collecting wireshark log.

    :param protocols: dict with bools ie. {'rrc': True}
    :param log_dir: full path to log directory
    :param run_remotely: if False tshark run local at VM, tcpdump run at eNb otherwise
    :return: list of tshark processes as pexpect instances
    """
    if run_remotely:
        platform = get_hw_type(logger=logger, data=enb_data)
        iface = "eth3" if platform == "FSMR3" else "br1"
        logger.debug("Platform detected: {}, set iface: {}".format(platform, iface))

        cmd = 'sshpass -p {} ssh {}@{} "nohup tcpdump -i {} sctp -w {} -s 0 &" &'.format(
            enb_data["passwd"], enb_data["user"], enb_data["host"], iface, enb_log
        )
        ret_code = call([cmd], universal_newlines=True, shell=True)
        logger.debug("Start tcpdump at eNb, RC: {}".format(ret_code))
        return ret_code
    else:
        proto_lists = [
            inner
            for inner in (
                sorted([proto for proto in protocols if not proto.startswith("rrc")]),
                [proto for proto in protocols if proto == "rrc_cus"],
                [proto for proto in protocols if proto == "rrc_iphy"],
                # [proto for proto in protocols if proto == "rrc_airphone"],
            )
            if inner
        ]
        logger.debug("Protocol list: {}".format(proto_lists))
        max_workers = len(proto_lists)
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            return [res for res in executor.map(start_tshark, proto_lists, [log_dir] * len(proto_lists)) if res]


def stop(tshark_processes, log_dir, is_x2, run_remotely=False):
    # type: (Union[List[Union[spawn, taf_admin]], int], str, bool, bool) -> None
    """
    Method should stop collecting wireshark log.
    :param tshark_processes: list of tshark processes started as pexpect instances
    :param log_dir: full path to log directory
    :param is_x2: bool value whether x2 protocol is used or not
    :param run_remotely: if False tshark run local at VM, tcpdupm run at eNb otherwise
    """
    if run_remotely:
        tcpdump_process, _ = run_remote_cmd(
            logger=logger, cmd="ps aux | grep -v grep | grep tcpdump | awk '{print $2}'", **enb_data
        )
        logger.debug("tcpdump PID: {}".format(tcpdump_process))

        run_remote_cmd(logger=logger, cmd="kill {}".format(tcpdump_process), **enb_data)

        copy_cmd = "sshpass -p{} scp {}@{}:{} {} > /dev/null 2>&1".format(
            enb_data["passwd"], enb_data["user"], enb_data["host"], enb_log, log_dir
        )
        ret_code = call([copy_cmd], universal_newlines=True, shell=True)
        logger.debug("RC: {} for cmd: {}".format(ret_code, copy_cmd))

        run_remote_cmd(logger=logger, cmd="rm /rom/logs/X2S1_lte_backhaul.pcap", **enb_data)
    else:
        for tshark_process in tshark_processes:
            pid = tshark_process.pid
            tshark_process.close()
            logger.debug("Tshark with PID {} closed.".format(pid))
        if is_x2:
            alias = X2AP_ALIAS_TEMPLATE.format("STOP", get_timestamp())
            try:
                with get_admin_connection(alias, log_dir) as admin_instance:
                    _mirroring_with_taf_admin(admin_instance, alias, enable=False)
            except Exception as err:
                logger.debug("Wasn't able to stop mirroring: {}".format(err))


@contextmanager
def wireshark(log_host, log_port, protocols, ue_sims, **kwargs):
    # type: (str, int, Dict[str, bool], List[str], **Any) -> None
    """
    Plugin for collecting wireshark data for X2, S1, M3 and RCC protocols.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    :param protocols: dict with bools i.e. {'rrc': True}
    :param ue_sims: list with str, used to start filters
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    logger.debug("Setting up wireshark filters for: {}".format(ue_sims))
    if "rrc" in protocols:
        del protocols["rrc"]
        if len(ue_sims) < 1:
            logger.warning("RRC was requested but no ue sim is selected! RRC will not be gathered.")
        for ue_sim in ue_sims:
            if ue_sim == "airphone":
                if "iphy" not in ue_sims:
                    ue_sim = "iphy"
                    logger.debug("Found AirPhone as simulator - going to use filter for IPhy")
                else:
                    logger.debug("Found AirPhone as simulator. IPhy is also used - not going to start another tshark.")
                    continue
            protocols["rrc_" + ue_sim] = True

    run_remotely = False
    if "sctp" in protocols and len(protocols) > 1:
        logger.warning(
            "SCTP (will be removed from request) is not allowed to be mixed with other protocols {}".format(protocols)
        )
        del protocols["sctp"]
    elif "sctp" in protocols and len(protocols) == 1:
        run_remotely = True

    tshark_processes = []  # type: List[spawn]
    try:
        tshark_processes = start(protocols, log_dir, run_remotely)
        yield
    finally:
        try:
            stop(tshark_processes, log_dir, "x2" in protocols, run_remotely)
        except TypeError:
            pass
        except Exception as err:
            logger.exception(err)
